Algoritmo Promedio
  Definir nota Como Entero;
  Definir suma Como Entero <- 0;
  Definir cantidad Como Entero <- 0;
  Leer nota;
  Mientras nota <> -1 Hacer
    suma <- suma + nota;
    cantidad <- cantidad + 1;
    Leer nota;
  FinMientras
  Si cantidad = 0 Entonces
    Escribir "No hay notas";
  Sino
    Escribir suma / cantidad;
  FinSi
FinAlgoritmo
